create extension if not exists pgcrypto;
do $$ begin create type conversation_type as enum ('direct','group'); exception when duplicate_object then null; end $$;
do $$ begin create type member_role as enum ('member','admin'); exception when duplicate_object then null; end $$;
do $$ begin create type message_type as enum ('text','image','video','document','voice','system'); exception when duplicate_object then null; end $$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade, username text unique not null check(username ~ '^[a-z0-9_]{3,24}$'), display_name text not null check(char_length(display_name) between 1 and 60), avatar_url text, about text not null default 'Using Hamemo', created_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(), type conversation_type not null default 'direct', title text, avatar_url text, description text default '', created_by uuid references public.profiles(id) on delete set null, last_message_id uuid, updated_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role member_role not null default 'member',muted_until timestamptz,pinned boolean not null default false,favorite boolean not null default false,archived boolean not null default false,draft text not null default '',cleared_at timestamptz,last_read_message_id uuid,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table if not exists public.messages(id uuid primary key,conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,type message_type not null default 'text',body text not null default '',media_url text,meta jsonb not null default '{}'::jsonb,reply_to_id uuid references public.messages(id) on delete set null,forwarded boolean not null default false,deleted_for_user_ids uuid[] not null default '{}',edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now());
create index if not exists idx_messages_conv_created_desc on public.messages(conversation_id,created_at desc,id desc);
create table if not exists public.message_receipts(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,delivered_at timestamptz default now(),read_at timestamptz,primary key(message_id,user_id));
create table if not exists public.message_reactions(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,emoji text not null check(char_length(emoji)<=16),created_at timestamptz not null default now(),primary key(message_id,user_id,emoji));
create table if not exists public.starred_messages(user_id uuid not null references public.profiles(id) on delete cascade,message_id uuid not null references public.messages(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,message_id));
create table if not exists public.blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id));
create or replace function public.is_conversation_member(conv_id uuid, uid uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.conversation_members where conversation_id=conv_id and user_id=uid) $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ declare uname text; begin uname:=lower(coalesce(new.raw_user_meta_data->>'username','user_'||substr(new.id::text,1,8))); if length(uname)<3 then uname:='user_'||substr(new.id::text,1,8); end if; insert into public.profiles(id,username,display_name) values(new.id,uname,coalesce(nullif(new.raw_user_meta_data->>'display_name',''),split_part(coalesce(new.email,''),'@',1),'User')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created_hamemo on auth.users; create trigger on_auth_user_created_hamemo after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security; alter table public.message_receipts enable row level security; alter table public.message_reactions enable row level security; alter table public.starred_messages enable row level security; alter table public.blocks enable row level security;
drop policy if exists profiles_select_auth on public.profiles; create policy profiles_select_auth on public.profiles for select to authenticated using(true); drop policy if exists profiles_update_self on public.profiles; create policy profiles_update_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
drop policy if exists conv_member_select on public.conversations; create policy conv_member_select on public.conversations for select to authenticated using(public.is_conversation_member(id)); drop policy if exists conv_create_auth on public.conversations; create policy conv_create_auth on public.conversations for insert to authenticated with check(created_by=auth.uid()); drop policy if exists conv_delete_creator on public.conversations; create policy conv_delete_creator on public.conversations for delete to authenticated using(created_by=auth.uid());
drop policy if exists members_select_member on public.conversation_members; create policy members_select_member on public.conversation_members for select to authenticated using(public.is_conversation_member(conversation_id)); drop policy if exists members_insert_creator on public.conversation_members; create policy members_insert_creator on public.conversation_members for insert to authenticated with check(exists(select 1 from public.conversations c where c.id=conversation_id and c.created_by=auth.uid()));
drop policy if exists messages_select_member on public.messages; create policy messages_select_member on public.messages for select to authenticated using(public.is_conversation_member(conversation_id)); drop policy if exists messages_insert_member on public.messages; create policy messages_insert_member on public.messages for insert to authenticated with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id)); drop policy if exists messages_update_sender on public.messages; create policy messages_update_sender on public.messages for update to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());
drop policy if exists receipts_member_select on public.message_receipts; create policy receipts_member_select on public.message_receipts for select to authenticated using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id))); drop policy if exists reactions_member_select on public.message_reactions; create policy reactions_member_select on public.message_reactions for select to authenticated using(exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id))); drop policy if exists reactions_self_insert on public.message_reactions; create policy reactions_self_insert on public.message_reactions for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.messages m where m.id=message_id and public.is_conversation_member(m.conversation_id))); drop policy if exists stars_self_all on public.starred_messages; create policy stars_self_all on public.starred_messages for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); drop policy if exists blocks_self_all on public.blocks; create policy blocks_self_all on public.blocks for all to authenticated using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
do $$ begin alter publication supabase_realtime add table public.messages; exception when duplicate_object then null; end $$;
